-- Default unit for bare numbers ("2 ail" = 2 gousses), used by the catalogue seed below.
alter table ingredients add column if not exists count_unit text;

-- Catalogue names in French.
update ingredients set name = 'Chou frisé (kale)' where household_id is null and name = 'Kale';
update ingredients set name = 'Croustilles de maïs' where household_id is null and name = 'Chips de maïs';
update ingredients set name = 'Croustilles de pita' where household_id is null and name = 'Chips de pita';
update ingredients set name = 'Sauce barbecue' where household_id is null and name = 'Sauce BBQ';
update ingredients set name = 'Pâte de fèves pimentée (doubanjiang)' where household_id is null and name = 'Doubanjiang';

-- Generated by scripts/build-seed.ts. Global ingredient catalogue.
begin;
update ingredients set count_unit = 'clove' where household_id is null and name = 'Ail';
update ingredients set count_unit = 'inch' where household_id is null and name = 'Gingembre';
commit;

-- Portions per week + whole multipliers + category filters (2026-09-29).

alter table week_plans add column if not exists portions int not null default 20;
alter table week_plans add column if not exists seasons text[];
alter table week_plans add column if not exists exclude_dish_types text[] not null default '{}';
alter table week_plan_recipes add column if not exists multiplier int not null default 1;

-- New catalogue item for the tofu recipes' side vegetables.

-- Corrections for recipes already imported (matched by title in every household).
update recipe_ingredients set raw = case position when 0 then '20 ml de sauce soya réduite en sodium (1 c. à thé)' when 1 then '20 ml de sauce aux huîtres (1 c. à thé)' when 2 then '20 ml de jus de lime (1 c. à thé)' when 3 then '10 ml de sirop d''érable (1/2 c. à thé)' when 4 then '4 pincées de sucre' when 5 then '180 ml de eau (3 c. à soupe)' when 6 then '20 ml de huile végétale (1 c. à thé)' when 7 then '1 paquet de tofu extra ferme (coupé en cubes; environ 110 g)' when 8 then '1 oignon (ciselé)' when 9 then '2 gousses de ail (hachée)' when 10 then '20 ml de gingembre frais (râpé; 1 c. à thé)' when 11 then '1 poivron rouge (coupé en cubes)' when 12 then '2 piment chili rouge (épépiné et tranché)' when 13 then '1 paquet de champignons shiitakes (tranchés finement; environ 55 g)' when 14 then '2 paquets de oignons verts (coupés en tronçons)' when 15 then '20 ml de graines de sésame (et plus pour la présentation; 1 c. à thé)' when 16 then '20 ml de mayonnaise (1 c. à thé)' when 17 then 'Arachides hachées, au goût' when 18 then '500 ml de féculents au choix (1/2 tasse)' else raw end where recipe_id in (select id from recipes where title = 'Sauté de tofu, oignons verts et sésame style philippino');
update recipe_ingredients set quantity = quantity * 4, quantity_max = quantity_max * 4 where recipe_id in (select id from recipes where title = 'Sauté de tofu, oignons verts et sésame style philippino' and servings = 1);
