update recipes set instructions = '["Dans une petite casserole, chauffer l’huile de sésame à feu moyen élevé et cuire les gousses d’ail 2 minutes en brassant souvent. Ajouter le reste des ingrédients de la sauce et laisser réduire environ 3 minutes.","Dans un bol, mélanger le tofu, la fécule de maïs et le sel.","Dans une poêle antiadhésive, chauffer l’huile à feu moyen-élevé et cuire le tofu pendant 5 à 6 minutes en brassant souvent, ou jusqu’à ce qu’il soit bien doré.","Dans une casserole d’eau bouillante salée, cuire les nouilles selon le temps de cuisson indiqué sur l’emballage. Égoutter.","Ajouter la sauce, les nouilles, le basilic et les oignons verts dans la poêle et mélanger délicatement jusqu’à ce que les nouilles soient bien enrobées de sauce. Servir avec les garnitures."]'::jsonb where title = 'Nouilles udon au tofu croustillant';
update recipes set instructions = '["Broyer les arachides et réserver.","Dans une poêle à frire, faire chauffer l’huile. Ajouter l’ail et le gingembre. Griller une ou deux minutes.","Ajouter la purée de piment, la sauce soja, le sirop d’érable, le vinaigre de riz et le beurre d’arachide. Bien mélanger.","Incorporer le lait de coco en brassant.","Retirer du feu et laisser refroidir.","Verser la sauce dans un saladier. Ajouter le reste des ingrédients et bien mélanger."]'::jsonb where title = 'Salade Thaï';
update recipes set instructions = '["Préchauffer le four à 400 F.","Dans une poêle à feu doux, faire suer l''ail, l''oignon et le gingembre dans le beurre.","Ajouter un peu d’huile d’olive, les épices, la pâte de tomate et les pois chiches, puis poursuivre la cuisson pendant environ 1 minute en remuant.","Incorporer le lait de coco, mélanger et laisser réduire la sauce pendant 5 minutes.","Goûter la sauce et rectifier l''assaisonnement (peut-être avec un peu de sel ou de poudre de chili si vous préférez que ce soit plus épicé).","Ajouter les morceaux de feta et envoyer au four. Cuire pendant 15 à 20 minutes ou jusqu''à ce que la feta soit bien cuite (il ne fondra pas, il gardera sa texture ferme). Retourner la feta à mi-cuisson.","Lorsque c''est prêt, servir immédiatement sur un lit de riz basmati et des naan ou simplement à même la poêle avec des pains naan en mode pique-assiette.","Parsemer de persil frais ou de coriandre fraîche finement hachée."]'::jsonb where title = 'Feta au four à l''indienne';

-- Vegetarian Moussaka for households that already have the starter recipes.
with h as (select distinct household_id from recipes where title = 'My Lasagne' and household_id not in (select household_id from recipes where title = 'Vegetarian Moussaka')),
r as (insert into recipes (household_id, title, source_type, source_url, image_url, servings, total_minutes, instructions, dish_type, protein, seasons) select household_id, 'Vegetarian Moussaka', 'url', 'https://www.allrecipes.com/recipe/25311/vegetarian-moussaka/', '/starter/images/vegetarian-moussaka.webp', 8, 155, '["Sprinkle eggplant slices with salt; set aside for 30 minutes. Rinse and pat dry with paper towels.","Preheat the oven to 375 degrees F (190 degrees C).","Heat olive oil in a large skillet over medium-high heat. Cook eggplant and zucchini in hot oil until lightly browned, about 3 minutes per side. Remove with a slotted spoon to drain on a paper towel-lined plate, reserving as much oil as possible in the skillet.","Add more oil to the skillet if needed and let it get hot. Cook potato slices in hot oil until browned, 3 to 5 minutes per side. Remove with a slotted spoon to drain on a paper towel-lined plate, again reserving oil in the skillet.","Sauté onion and garlic in reserved oil until lightly browned, 5 to 7 minutes. Pour in vinegar, bring to a boil, and reduce heat to medium-low; cook until liquid is reduced in volume and thick. Stir in tomatoes, lentils, 1/2 of the juice from lentils, parsley, and oregano. Season with salt and black pepper. Cover, reduce heat to medium-low, and simmer for 15 minutes.","Layer about 1/3 of the eggplant, 1/3 of the zucchini, 1/2 of the potatoes, and 1/2 of the feta in a 9x13-inch baking dish. Pour 1/2 of the tomato mixture over vegetables; repeat layering, finishing with a layer of eggplant and zucchini.","Cover and bake in the preheated oven for 25 minutes.","Meanwhile, make the sauce: Stir milk, flour, and butter for together in a small saucepan; bring to a low boil, whisking constantly, until thick and smooth. Season with nutmeg and black pepper. Remove from heat, cool for 5 minutes, and stir in beaten egg.","Pour sauce over vegetables and top with Parmesan cheese. Continue baking, uncovered, until sauce is bubbly and top is lightly brown, 25 to 30 minutes."]'::jsonb, 'four', 'légumineuses', array['automne', 'hiver']::text[] from h returning id)
select r.id, v.position, v.section, v.raw, v.quantity::numeric, v.quantity_max::numeric, v.unit, v.name, v.note, v.optional, i.id
from r cross join (values
  (0, null, '1 eggplant, thinly sliced', 1, null, null, 'eggplant', 'thinly sliced', false, 'Aubergine'),
  (1, null, '1 teaspoon salt, or more as needed', 1, null, 'tsp', 'salt', 'or more as needed', false, 'Sel'),
  (2, null, '1 tablespoon olive oil, or more as needed', 1, null, 'tbsp', 'olive oil', 'or more as needed', false, 'Huile d''olive'),
  (3, null, '1 large zucchini, thinly sliced', 1, null, null, 'zucchini', 'thinly sliced; large', false, 'Courgette'),
  (4, null, '2 potatoes, thinly sliced', 2, null, null, 'potatoes', 'thinly sliced', false, 'Pomme de terre'),
  (5, null, '1 onion, sliced', 1, null, null, 'onion', 'sliced', false, 'Oignon jaune'),
  (6, null, '1 clove garlic, chopped', 1, null, 'clove', 'garlic', 'chopped', false, 'Ail'),
  (7, null, '1 tablespoon white vinegar', 1, null, 'tbsp', 'white vinegar', null, false, 'Vinaigre blanc'),
  (8, null, '1 (14.5 ounce) can whole peeled tomatoes, chopped', 1, null, 'can', 'whole peeled tomatoes', 'chopped; 14.5 ounce', false, 'Tomates entières (conserve)'),
  (9, null, '½ (14.5 ounce) can lentils, drained with liquid reserved', 0.5, null, 'can', 'lentils', 'drained with liquid reserved; 14.5 ounce', false, 'Lentilles brunes (conserve)'),
  (10, null, '2 tablespoons chopped fresh parsley', 2, null, 'tbsp', 'chopped fresh parsley', null, false, 'Persil frais'),
  (11, null, '1 teaspoon dried oregano', 1, null, 'tsp', 'dried oregano', null, false, 'Origan séché'),
  (12, null, 'ground black pepper to taste', null, null, null, 'ground black pepper', 'to taste', false, 'Poivre noir'),
  (13, null, '1 cup crumbled feta cheese', 1, null, 'cup', 'crumbled feta cheese', null, false, 'Feta'),
  (14, 'Sauce', '1 ¼ cups milk', 1.25, null, 'cup', 'milk', null, false, 'Lait'),
  (15, 'Sauce', '2 tablespoons all-purpose flour', 2, null, 'tbsp', 'all-purpose flour', null, false, 'Farine tout usage'),
  (16, 'Sauce', '1 ½ tablespoons butter', 1.5, null, 'tbsp', 'butter', null, false, 'Beurre'),
  (17, 'Sauce', '1 pinch ground nutmeg', 1, null, 'pinch', 'ground nutmeg', null, false, 'Muscade'),
  (18, 'Sauce', 'ground black pepper to taste', null, null, null, 'ground black pepper', 'to taste', false, 'Poivre noir'),
  (19, 'Sauce', '1 large egg, beaten', 1, null, null, 'egg', 'beaten; large', false, 'Œufs'),
  (20, 'Topping', '¼ cup grated Parmesan cheese', 0.25, null, 'cup', 'grated Parmesan cheese', null, false, 'Parmesan')
) v(position, section, raw, quantity, quantity_max, unit, name, note, optional, catalog)
left join ingredients i on i.household_id is null and i.name = v.catalog;
